import{_ as e,o as d,c as a,ag as i}from"./chunks/framework.Ca42NP5A.js";const u=JSON.parse('{"title":"AM_EVAL_JOYSTICKS","description":"","frontmatter":{},"headers":[],"relativePath":"am_eval_joysticks/index.md","filePath":"am_eval_joysticks/README.md"}'),r={name:"am_eval_joysticks/index.md"};function o(l,t,c,n,s,_){return d(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="am-eval-joysticks" tabindex="-1">AM_EVAL_JOYSTICKS <a class="header-anchor" href="#am-eval-joysticks" aria-label="Permalink to &quot;AM_EVAL_JOYSTICKS&quot;">​</a></h1><p>Status: <span class="device-badge device-badge--no-hardware">EVAL</span></p><p>Evaluation board for joystick and operator-control input bring-up on STM32F103.</p><p>Main interfaces:</p><ul><li>CAN;</li><li>I2C on PB6/PB7;</li><li>board power/current ADC inputs;</li><li>joystick-related input pins.</li></ul><h2 id="pinout" tabindex="-1">Pinout <a class="header-anchor" href="#pinout" aria-label="Permalink to &quot;Pinout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>MCU configuration</th></tr></thead><tbody><tr><td>PA10</td><td>BT1 / LIVE_N</td><td>GPIO input</td></tr><tr><td>PA9</td><td>BT2 / INC_N</td><td>GPIO input</td></tr><tr><td>PB0</td><td>BT3 / DEC_N</td><td>ADC1_IN8</td></tr><tr><td>PB3</td><td>SWA1 / LEFT_N relay</td><td>GPIO input</td></tr><tr><td>PB4</td><td>SWA2 relay</td><td>GPIO input</td></tr><tr><td>PA2</td><td>OUT1 / side</td><td>ADC1_IN2</td></tr><tr><td>PA5</td><td>OUT2 / travel</td><td>ADC1_IN5</td></tr><tr><td>PA6</td><td>OUT3 / DIAG</td><td>ADC1_IN6</td></tr><tr><td>PB7</td><td>I2C SDA</td><td>I2C1_SDA</td></tr><tr><td>PB6</td><td>I2C SCL</td><td>I2C1_SCL</td></tr><tr><td>PA0</td><td>VIN</td><td>ADC1_IN0</td></tr><tr><td>PA4</td><td>3SWA / BACK_N relay</td><td>GPIO input</td></tr><tr><td>PA3</td><td>4SWA / FWD_N relay</td><td>GPIO input</td></tr><tr><td>Internal</td><td>MCU temperature</td><td>ADC1 temperature sensor</td></tr></tbody></table><p>PA9, PA10, PB3, and PB4 are not ADC-capable pins on STM32F103 and are configured as GPIO inputs.</p><h2 id="bring-up-notes" tabindex="-1">Bring-up notes <a class="header-anchor" href="#bring-up-notes" aria-label="Permalink to &quot;Bring-up notes&quot;">​</a></h2><p>Current joystick observations:</p><ul><li><code>cid=1</code> (<code>eval.pa10_bt1_live_n.cid</code>) is BT1/LIVE_N: 0 V live, 3.3 V dead.</li><li><code>cid=2</code> (<code>eval.pa9_bt2_inc_n.cid</code>) is BT2/INC_N: 0 V increased, 3.3 V otherwise.</li><li><code>cid=3</code> (<code>eval.pb0_bt3_dec_n.cid</code>) is BT3/DEC_N: 0 V decreased, 3.3 V otherwise.</li><li><code>cid=4</code> (<code>eval.pb3_swa1_left_n.cid</code>) is SWA1/LEFT_N relay: 0 V slightly left, 3.3 V otherwise.</li><li><code>cid=5</code> (<code>eval.pb4_swa2_relay.cid</code>) is SWA2 relay: always 3.3 V during bring-up.</li><li><code>cid=6</code> (<code>eval.pa2_out1_side.cid</code>) is OUT1/side: 0 V left, about 3.0 V right.</li><li><code>cid=7</code> (<code>eval.pa5_out2_travel.cid</code>) is OUT2/travel: about 3.0 V forward, 0 V backward.</li><li><code>cid=8</code> (<code>eval.pa6_out3_diag.cid</code>) is OUT3/DIAG: constant about 1.7 V during bring-up.</li><li><code>cid=10</code> (<code>eval.pa4_3swa_back_n.cid</code>) is 3SWA/BACK_N relay: 0 V slightly backward, 3.3 V otherwise.</li><li><code>cid=11</code> (<code>eval.pa3_4swa_fwd_n.cid</code>) is 4SWA/FWD_N relay: 0 V slightly forward, 3.3 V otherwise.</li><li>OUT3 is DIAG for sure; DIAG behavior needs re-check after the latest hardware change.</li><li>Buttons and other joystick features do not work or have not been identified yet.</li></ul><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><ul><li><a href="./firmware_am_eval_joysticks">am_eval_joysticks</a></li></ul>',13)])])}const h=e(r,[["render",o]]);export{u as __pageData,h as default};
